# Immutable snapshots: runtime prompt edits must not rewrite this transition.
OLD = "Операция: intro.\nНапиши короткое художественное вступление для страницы города в «Инвольта гиде» — личном рейтинге Алекса. Верни JSON по схеме.\nВступление существует независимо от ресторанной подборки. Передай настроение города, его характер и предвкушение еды. Опирайся только на достоверно известные факты из контекста или общеизвестные особенности; не выдумывай достопримечательности, местные блюда или собственные посещения. Не перечисляй рестораны, не обещай конкретную тройку. Не объясняй методологию, сбор источников, оценки и внутреннее устройство гида. Без канцелярита, рекламных клише и выдуманной личной дегустации. Достаточно 2–4 живых предложений на русском.\nТекущий текст дан для контекста обновления; создай законченную новую редакцию. Только intro, никаких ресторанных данных."
NEW = 'Операция: intro.\nНапиши короткое вступление для страницы города или района в «Инвольта гиде».\n\nЧитатель приехал впервые, возможно проездом и ненадолго. Объясни простыми живыми словами, что здесь стоит заметить за короткий приезд. Говори как знакомый местный, на «вы»; прямое обращение необязательно.\n\nВыбери одну узнаваемую особенность, которую гость может увидеть или почувствовать: облик города, его история в сегодняшних улицах, природа рядом или местная жизнь. Несколько связанных деталей могут составить одно впечатление. Для района описывай именно район.\n\nНе подменяй впечатление бытовой памяткой: адресация, парковка, транспортные схемы и другие правила пользования городом не подходят для вступления. Даже необычный факт должен помогать представить само место.\n\nМожно дать один короткий совет, но не превращай каждый текст в указание куда идти. Не начинай автоматически с «В [городе]» или «Начните с». Название уже есть в заголовке.\n\nПиши разговорно, без поэтических метафор, торжественного тона, рекламных обещаний и пустых слов о «духе» и «атмосфере». Еда необязательна; универсальные концовки про обед, ужин и прогулку не нужны. Не перечисляй рестораны, не объясняй методологию гида и не изображай личный опыт.\n\nИспользуй контекст и достоверно известные факты. Не выдумывай особенности места, доступность объектов, маршруты и время в пути.\n\nОдно законченное предложение на русском, 50–100 символов с пробелами и пунктуацией, ориентир 70–90. Без заголовка и переносов строк. Перед ответом проверь длину, естественность речи и наличие характерной детали именно этого места.\n\nВерни только JSON по схеме: {"intro":"..."}.\n'


def replace_default(before: str, after: str) -> None:
    op.execute(
        text(
            "UPDATE settings SET value=:after WHERE key='content_intro_prompt' "
            "AND btrim(replace(value, chr(13), ''), chr(10) || chr(9) || ' ')=:before"
        ).bindparams(before=before.strip(), after=after)
    )


def upgrade() -> None:
    replace_default(OLD, NEW)


def downgrade() -> None:
    replace_default(NEW, OLD + "\n")
